import { useEffect, useState } from "react";
import Loader from "react-loaders";
import AnimatedLetters from "../AnimatedLetters";
import useInView from "../../hooks/useInView";
import "./index.scss";

const Portfolio = () => {
  const [letterClass, setLetterClass] = useState("text-animate");
  const [ref, inView] = useInView();

  useEffect(() => {
    const timer = setTimeout(() => {
      setLetterClass("text-animate-hover");
    }, 3000);

    return () => clearTimeout(timer);
  }, []);

  return (
    <>
      <div
        id="portfolio"
        ref={ref}
        className={`container portfolio-page fade-section ${
          inView ? "in-view" : ""
        }`}
      >
        <div className="text-zone">
          <h1>
            <AnimatedLetters
              letterClass={letterClass}
              strArray={"My Portfolio".split("")}
              index={15}
            />
          </h1>
          <p>
            A selection of projects that reflect how I like to build: practical,
            data-driven, and focused on real user workflows—from fantasy sports
            optimization, to dynamic fitness tracking, to tooling for the
            Pokémon TCG.
          </p>
        </div>

        <div className="projects-grid">
          {/* DraftKings */}
          <div className="project-card">
            {/* If you had an image/gif before, put it back here */}

            <h3>DraftKings NBA Lineup Recommender</h3>
            <p>
              Full-stack tool that ingests DraftKings salary CSVs, calculates
              player efficiency, and generates optimized NBA lineups under the
              salary cap.
            </p>

            <div className="project-links">
              <a
                href="https://github.com/capisz/draftkings-optimizer"
                target="_blank"
                rel="noreferrer"
                className="flat-button small secondary"
              >
                VIEW CODE
              </a>
            </div>
          </div>

          {/* Dragapultist */}
          <div className="project-card">
            {/* If you had an image/gif before, put it back here */}

            <h3>Dragapultist – Pokémon TCG Analyzer</h3>
            <p>
              Deck analysis tool for Pokémon TCG Live that imports card IDs,
              uses the TCGdex SDK to fetch metadata, shuffles decks, simulates
              prize cards, and helps track matchups.
            </p>

            <div className="project-links">
              <a
                href="https://github.com/capisz/dragapultist"
                target="_blank"
                rel="noreferrer"
                className="flat-button small secondary"
              >
                VIEW CODE
              </a>
            </div>
          </div>

          {/* Elephit */}
          <div className="project-card">
            {/* If you had an image/gif before, put it back here */}

            <h3>Elephit – Dynamic Calorie Tracker</h3>
            <p>
              A dynamic alternative to MyFitnessPal that adjusts calorie targets
              based on weight trends, rewarding consistency and adapting macros
              as the user’s body changes.
            </p>

            <div className="project-links">
              <a
                href="https://github.com/capisz/elephit-fitness-app"
                target="_blank"
                rel="noreferrer"
                className="flat-button small secondary"
              >
                VIEW CODE
              </a>
            </div>
          </div>
        </div>
      </div>

      <Loader type="pacman" />
    </>
  );
};

export default Portfolio;
